const seniorTopics={"daily": ["ne-adrc", "ne-cil-independence-rising", "ne-cil-lhd-lincoln", "ne-cil-lhd-norfolk", "ne-cil-lhd-omaha"], "accessibility": ["ne-adrc", "ne-cil-independence-rising", "ne-cil-lhd-lincoln", "ne-cil-lhd-norfolk", "ne-cil-lhd-omaha"], "vision": ["ne-adrc"], "hearing": ["ne-adrc"], "memory": ["alz-dementia-support", "ne-adrc"], "costs": ["ne-ship", "ne-adrc", "ne-legal-programs"], "rights": ["ne-ombudsman", "ne-legal-programs"]};
const ohioLiving=DATA.filter(x=>x.resource_role==='independent_living').map(x=>x.program_id),ohioCaregivers=DATA.filter(x=>x.resource_role==='caregiver_support').map(x=>x.program_id);
